/**
 * The tuning panel. Loaded with a dynamic import the first time the debug tools are shown,
 * so lil-gui stays out of the main bundle. The tunable controls are generated from
 * TUNABLE_SPECS, so a new tunable appears here without touching this file.
 */
import GUI, { type Controller } from 'lil-gui';
import './panel.css';
import { DEFAULT_TUNABLES, TUNABLE_SPECS, type TunableKey } from '../config/tunables';
import { tunablesDiffJson } from '../config/tunablesStore';
import type { CameraDevice, SourceInfo } from '../vision/types';
import { errorMessage } from './format';
import type { Level } from './hudModel';
import type { DebugDeps } from './types';

const FOLDERS_KEY = 'surf-game.debug-folders';
const CAMERA_FOLDER = 'Camera & clips';
/**
 * Folders open on first use: the camera tools, and the tunables that matter for judging how
 * the ride plays.
 */
const DEFAULT_OPEN = [CAMERA_FOLDER, 'Control', 'Ride'];
const FLASH_MS = 2000;
const RESET_CONFIRM_MS = 3000;
/** Opening another camera usually takes a second or two. */
const SWITCH_GRACE_MS = 5000;

export interface PanelHost {
  deps: DebugDeps;
  notify(text: string, level?: Level): void;
  loadClipFile(file: File): void;
  switchCamera(deviceId: string, name: string): void;
  toggleRecording(): void;
}

export interface Panel {
  onShow(): void;
  onHide(): void;
  /** Called on every HUD refresh; cheap unless the source changed. */
  sync(): void;
  setRecording(recording: boolean, label: string): void;
  destroy(): void;
}

interface FolderState {
  open: string[];
  collapsed: boolean;
}

function loadFolderState(): FolderState {
  try {
    const saved = JSON.parse(localStorage.getItem(FOLDERS_KEY) ?? 'null') as FolderState | null;
    if (saved && Array.isArray(saved.open))
      return { open: saved.open, collapsed: !!saved.collapsed };
  } catch {
    // Fall through to the defaults.
  }
  return { open: DEFAULT_OPEN, collapsed: false };
}

function saveFolderState(gui: GUI): void {
  try {
    const state: FolderState = {
      open: gui.folders.filter((folder) => !folder._closed).map((folder) => folder._title),
      collapsed: gui._closed,
    };
    localStorage.setItem(FOLDERS_KEY, JSON.stringify(state));
  } catch {
    // Persistence is a convenience.
  }
}

/** Dropdown entries for the camera picker: unique names mapped to device ids. */
function cameraEntries(cameras: readonly CameraDevice[]): Array<[string, string]> {
  const used = new Set<string>();
  const entries: Array<[string, string]> = [];
  cameras.forEach((camera, index) => {
    // Without permission devices have no id, and there is nothing to switch to.
    if (!camera.deviceId) return;
    let name = camera.label.trim() || `Camera ${index + 1}`;
    for (let n = 2; used.has(name); n++) name = `${camera.label.trim() || 'Camera'} (${n})`;
    used.add(name);
    entries.push([name, camera.deviceId]);
  });
  return entries;
}

function sourceKey(info: SourceInfo | null | undefined): string {
  return info ? `${info.kind}|${info.deviceId}` : '';
}

export function createPanel(container: HTMLElement, host: PanelHost): Panel {
  const { deps } = host;
  const folderState = loadFolderState();
  const gui = new GUI({ container, title: 'Debug tools' });
  const timers = new Map<Controller, ReturnType<typeof setTimeout>>();
  let destroyed = false;

  // --- Actions on the tunables --------------------------------------------------------

  const changedCount = (): number =>
    (Object.keys(TUNABLE_SPECS) as TunableKey[]).filter(
      (key) => deps.tunables[key] !== DEFAULT_TUNABLES[key],
    ).length;
  const copyLabel = (): string => {
    const count = changedCount();
    return count ? `Copy changes as JSON (${count})` : 'Copy changes as JSON';
  };

  /** Show `label` on a button for a moment, then put back its normal label. */
  const flash = (controller: Controller, label: string, normal: () => string, ms = FLASH_MS) => {
    clearTimeout(timers.get(controller));
    controller.name(label);
    timers.set(
      controller,
      setTimeout(() => {
        timers.delete(controller);
        controller.name(normal());
      }, ms),
    );
  };

  let resetArmedUntil = 0;
  const tools = {
    copy: () => void copyChanges(),
    reset: () => reset(),
  };
  const copyController = gui.add(tools, 'copy').name(copyLabel());
  const resetController = gui.add(tools, 'reset').name('Reset to defaults');

  const copyChanges = async (): Promise<void> => {
    const json = tunablesDiffJson(deps.tunables);
    const count = changedCount();
    const what = count === 1 ? '1 change' : `${count} changes`;
    try {
      await navigator.clipboard.writeText(json);
      if (destroyed) return;
      flash(copyController, count ? `Copied ${what} ✓` : 'Copied {} ✓ (no changes)', copyLabel);
      host.notify(
        count ? `Copied ${what} as JSON.` : 'Nothing differs from the defaults; copied {}.',
      );
    } catch {
      if (destroyed) return;
      console.info(`Tunable changes:\n${json}`);
      flash(copyController, 'Copy failed: see console', copyLabel);
      host.notify('The clipboard is unavailable, so the JSON was printed to the console.', 'warn');
    }
  };

  const reset = (): void => {
    const count = changedCount();
    const now = performance.now();
    // Two clicks, so one stray click cannot throw away a tuning session.
    if (count > 0 && now > resetArmedUntil) {
      resetArmedUntil = now + RESET_CONFIRM_MS;
      const what = count === 1 ? '1 change' : `${count} changes`;
      flash(
        resetController,
        `Click again to discard ${what}`,
        () => 'Reset to defaults',
        RESET_CONFIRM_MS,
      );
      return;
    }
    resetArmedUntil = 0;
    deps.actions.resetTunables();
    refreshTunables();
    flash(resetController, 'Reset ✓', () => 'Reset to defaults');
    host.notify('Every tunable is back to its default.');
  };

  // --- Camera and clips ---------------------------------------------------------------

  const sourceFolder = gui.addFolder(CAMERA_FOLDER);
  const cameraState = { camera: '' };
  let cameras: CameraDevice[] = [];
  let entries: Array<[string, string]> = [];
  let lastVision: unknown = null;
  let lastSource = '';
  let listTicket = 0;
  /** Until then the picker may show a camera the source has not switched to yet. */
  let switchSettlesAt = 0;

  const cameraController = sourceFolder
    .add(cameraState, 'camera', { 'Not started': '' })
    .name('Camera')
    .onChange((deviceId: string) => {
      const vision = deps.getVision();
      const current = vision?.sourceInfo;
      if (!deviceId || (current?.kind === 'camera' && current.deviceId === deviceId)) return;
      if (!vision) {
        host.notify('Start the game first, then switch cameras.', 'warn');
        rebuildCameraOptions();
        return;
      }
      const name = entries.find(([, id]) => id === deviceId)?.[0] ?? 'the camera';
      switchSettlesAt = performance.now() + SWITCH_GRACE_MS;
      host.switchCamera(deviceId, name);
    });

  /** The picker value that matches the running source ('' is the placeholder). */
  const currentValue = (info: SourceInfo | null): string =>
    info?.kind === 'camera' && entries.some(([, id]) => id === info.deviceId)
      ? (info.deviceId ?? '')
      : '';

  const rebuildCameraOptions = (): void => {
    const info = deps.getVision()?.sourceInfo ?? null;
    entries = cameraEntries(cameras);
    const options: Record<string, string> = {};
    const value = currentValue(info);
    // A placeholder names the current source when it is not one of the listed cameras.
    if (!info) options['Not started'] = '';
    else if (info.kind !== 'camera')
      options[info.kind === 'clip' ? 'Clip playing' : 'Synthetic'] = '';
    else if (!value) options[info.label || 'Current camera'] = '';
    for (const [name, id] of entries) options[name] = id;
    cameraState.camera = value;
    cameraController.options(options);
  };

  const refreshCameras = (): void => {
    const ticket = ++listTicket;
    deps.actions.listCameras().then(
      (list) => {
        if (destroyed || ticket !== listTicket) return;
        cameras = list;
        rebuildCameraOptions();
      },
      (error: unknown) => host.notify(`Could not list cameras: ${errorMessage(error)}`, 'bad'),
    );
  };

  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.accept = 'video/*,.webm,.mp4,.mov,.mkv';
  fileInput.hidden = true;
  fileInput.addEventListener('change', () => {
    const file = fileInput.files?.[0];
    // Cleared so picking the same file again still fires `change`.
    fileInput.value = '';
    if (file) host.loadClipFile(file);
  });
  container.appendChild(fileInput);

  const clipActions = {
    loadClip: () => fileInput.click(),
    record: () => host.toggleRecording(),
  };
  sourceFolder.add(clipActions, 'loadClip').name('Load clip…');
  const recordController = sourceFolder.add(clipActions, 'record').name('Record clip');
  recordController.domElement.classList.add('dbg-record');

  // --- Tunables, generated from the specs ---------------------------------------------

  const tunableControllers: Array<{ key: TunableKey; controller: Controller }> = [];
  const groups = new Map<string, GUI>();

  const markChanged = (): void => {
    for (const { key, controller } of tunableControllers) {
      controller.domElement.classList.toggle(
        'dbg-changed',
        deps.tunables[key] !== DEFAULT_TUNABLES[key],
      );
    }
    if (!timers.has(copyController)) copyController.name(copyLabel());
  };

  const refreshTunables = (): void => {
    for (const { controller } of tunableControllers) controller.updateDisplay();
    markChanged();
  };

  for (const key of Object.keys(TUNABLE_SPECS) as TunableKey[]) {
    const spec = TUNABLE_SPECS[key];
    let folder = groups.get(spec.group);
    if (!folder) {
      folder = gui.addFolder(spec.group);
      groups.set(spec.group, folder);
    }
    const controller =
      spec.kind === 'number'
        ? folder.add(deps.tunables, key, spec.min, spec.max, spec.step)
        : folder.add(deps.tunables, key);
    controller.name(spec.label).onChange(() => {
      deps.onTunablesChanged();
      markChanged();
    });
    tunableControllers.push({ key, controller });
  }

  for (const folder of gui.folders) folder.open(folderState.open.includes(folder._title));
  gui.open(!folderState.collapsed);
  gui.onOpenClose(() => saveFolderState(gui));
  markChanged();

  // --- Focus ----------------------------------------------------------------------------
  // lil-gui stops key events inside its controls so typing into a field cannot trigger
  // game shortcuts. That would also swallow F, M and D after a mere click on a button, so
  // keep focus out of the panel unless the user is typing into a field.

  const onMouseDown = (event: MouseEvent): void => {
    const target = event.target as Element;
    if (target.closest('button, .lil-boolean, .lil-slider')) event.preventDefault();
  };
  const onChange = (event: Event): void => {
    if (event.target instanceof HTMLSelectElement) event.target.blur();
  };
  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== 'Escape') return;
    const target = event.target;
    if (target instanceof HTMLInputElement || target instanceof HTMLSelectElement) target.blur();
  };
  container.addEventListener('mousedown', onMouseDown, true);
  container.addEventListener('change', onChange);
  container.addEventListener('keydown', onKeyDown, true);

  const onDeviceChange = (): void => refreshCameras();
  let listening = false;
  const listenForDevices = (on: boolean): void => {
    if (on === listening) return;
    listening = on;
    if (on) navigator.mediaDevices?.addEventListener('devicechange', onDeviceChange);
    else navigator.mediaDevices?.removeEventListener('devicechange', onDeviceChange);
  };

  return {
    onShow() {
      // Values can change behind the panel's back (reset, tests), so re-read them.
      refreshTunables();
      refreshCameras();
      listenForDevices(true);
    },
    onHide() {
      listenForDevices(false);
    },
    sync() {
      const vision = deps.getVision();
      // Device labels become readable once the game has opened the camera.
      if (vision !== lastVision) {
        lastVision = vision;
        refreshCameras();
      }
      const info = vision?.sourceInfo ?? null;
      const key = sourceKey(info);
      // A switch that failed (or never happened) must not leave the picker showing it.
      const stale =
        performance.now() > switchSettlesAt && cameraState.camera !== currentValue(info);
      if (key !== lastSource || stale) {
        lastSource = key;
        rebuildCameraOptions();
      }
    },
    setRecording(recording, label) {
      if (recordController._name !== label) recordController.name(label);
      recordController.domElement.classList.toggle('dbg-recording', recording);
    },
    destroy() {
      destroyed = true;
      listenForDevices(false);
      for (const timer of timers.values()) clearTimeout(timer);
      timers.clear();
      container.removeEventListener('mousedown', onMouseDown, true);
      container.removeEventListener('change', onChange);
      container.removeEventListener('keydown', onKeyDown, true);
      fileInput.remove();
      gui.destroy();
    },
  };
}
